    while True:
        line = sys.stdin.readline()
        if not line:
            break
        cmd = line.strip()
        if cmd == "uci":
            send("id name DummyNeg")
            send("id author AI")
            send("uciok")
        elif cmd == "isready":
            send("readyok")
        elif cmd.startswith("position"):
            # Update internal board for simple move generation
            try:
                parts = cmd.split()
                if "startpos" in parts:
                    board.set_fen(chess.STARTING_FEN)
                    moves_index = parts.index("startpos") + 1
                else:
                    fen_parts = parts[1:]
                    fen = " ".join(fen_parts[:6])
                    board.set_fen(fen)
                    moves_index = 7  # after fen tokens
                if moves_index < len(parts) and parts[moves_index] == "moves":
                    for uci in parts[moves_index+1:]:
                        move = chess.Move.from_uci(uci)
                        board.push(move)
            except Exception:
                pass
        elif cmd.startswith("go"):
            # always output big negative score and choose a random legal move or null move
            score_cp = -10000
            send(f"info score cp {score_cp}")
            legal_moves = list(board.legal_moves)
            if legal_moves:
                mv = random.choice(legal_moves)
                send(f"bestmove {mv.uci()}")
            else:
                send("bestmove 0000")
        elif cmd == "quit":
            break
        elif cmd == "ucinewgame":
            board.reset()
    sys.exit(0)

if __name__ == "__main__":
    main()
